dir:

































































































































	select data as id into #id from dbo.ISWIFTFunction$Split(@so_ct, ',')
	select @@fields into #t from v41 a @@join
	  where a.id in (select id from #id)
	  order by a.line, a.id

	select id_bg, line_bg, sum(a.so_luong) as sl_bao_gia into #sl from g11 a with(index(id_bg)) where id <> @id and id_bg <> 0 and exists(select 1 from #t b where a.id_bg = b.id_bg and a.line_bg = b.line_bg) group by id_bg, line_bg
	update #t set sl_cl = a.so_luong - isnull(b.sl_bao_gia, 0) from #t a left join #sl b on a.id_bg = b.id_bg and a.line_bg = b.line_bg
	update #t set so_luong0 = sl_cl
	select * from #t where sl_cl <> 0


	DECLARE @dl_yn int, @ncc_yn int,@ma_hang varchar(32),@ten_hang nvarchar(255),@ma_dl varchar(32)

	DECLARE @tma_kh table (ma_hang varchar(32), ten_hang nvarchar(256), dl_yn int, ncc_yn int)
	insert into @tma_kh select a.ma_hang, d.ten_hang, d.dl_yn, d.ncc_yn from s41 a 
	  left join vdmhangtau d on a.ma_hang =d.ma_hang 
	where a.id in (select top 1 id from #id order by id desc)

	select @dl_yn = dl_yn, @ncc_yn = ncc_yn, @ma_hang = ma_hang,@ten_hang = ten_hang, @ma_dl = ma_hang from @tma_kh

	select a.ma_noi_di,a.ma_noi_den,a.ma_kh,a.ma_nt, iif(@ncc_yn = 1, @ma_hang,'') ma_hang,iif(@dl_yn = 1, @ma_dl,'') ma_dl,
	b.ten_noi_di,c.ten_noi_den,d.ten_kh,e.ten_hang, iif(@dl_yn = 1, @ten_hang,'') ten_dl, a.ngay_hl, a.ngay_hld, a.ma_gd, id id_bg, a.id_yc from s41 a 
	  left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di 
	  left join vdmcangden c on a.ma_noi_den =c.ma_noi_den 
	  left join dmkh d on a.ma_kh =d.ma_kh 
	  left join vdmhangtau e on a.ma_hang = e.ma_hang
	where a.id in (select top 1 id from #id order by id desc)

	drop table #id, #t, #sl









  &DefaultButton;




function filter$l11BQ1Select(p){
  this.constructor(p);
}
filter$l11BQ1Select.prototype = new DirEvent();
filter$l11BQ1Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$l11BQ1Select.prototype.afterInit = function(){
  var p = this._dir;
  p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den','ma_kh','ten_kh', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,p.options._ma_kh, p.options._ten_kh,  p.options._ma_nt, p.options._unit_id]);
	dir$l11BQ1SetMaster(p);

}

function dir$l11BQ1SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$l11BQ1Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(0), dt = g.data, master = g.ds.get(1), rErr = dt.findRow("[so_luong0] > [sl_cl]");

  var fun = function(){
    dt.removeRow('[so_luong0] == 0'); 
    pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'so_luong', 'so_luong0');
    pa.calcExpressionAll(0, 'so_luong');
	//p.request('ma_kh_request', '', ['id']);
    pa.appendForm(master, 0);
	p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();

    return false;
}










					select top 1 a.id_yc as [!id_yc], a.ma_kh as [!ma_kh],d.ten_kh as [!ten_kh],a.ma_hang as [!ma_hang], a.ma_noi_di as [!ma_noi_di], a.ma_noi_den as [!ma_noi_den],
					b.ten_noi_di as [!ten_noi_di],c.ten_noi_den as [!ten_noi_den], e.ten_kh as [!ten_hang],a.so_ct as [!so_ct]
					from s41 a left join vdmcangdi b on a.ma_noi_di =b.ma_noi_di left join vdmcangden c on a.ma_noi_den =c.ma_noi_den left join dmkh d on a.ma_kh =d.ma_kh left join dmkh e on a.ma_hang =e.ma_kh
					where a.id = @id
